50	async function apiFetch<T>(path: string): Promise<T> {
51	  const res = await fetch(`${API_URL}${path}`, { cache: "no-store" });
52	  if (!res.ok) {
53	    throw new Error(`API error: ${res.status}`);
54	  }
55	  return res.json();
56	}
57	
58	export function fetchOverview(
59	  tenantId: string = "default"
60	): Promise<OverviewStats> {
61	  return apiFetch(`/v1/overview?tenant_id=${tenantId}`);
62	}
63	
64	export function fetchProjects(): Promise<ProjectSummary[]> {
65	  return apiFetch("/v1/projects");
66	}
67	
68	export function fetchProjectStats(projectDir: string): Promise<ProjectStats> {
69	  const encoded = projectDir.replaceAll("/", "|");
70	  return apiFetch(`/v1/projects/${encodeURIComponent(encoded)}/stats`);
71	}
72	
73	export function fetchSavingsTrend(days: number = 30): Promise<DailySavings[]> {
74	  return apiFetch(`/v1/savings/trend?days=${days}`);
75	}
76	
77	export function formatTokens(n: number): string {
78	  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(1)}M`;
79	  if (n >= 1_000) return `${(n / 1_000).toFixed(1)}K`;
80	  return n.toString();
81	}
82	
83	export function estimateCost(tokens: number): string {
84	  const costPer1k = 0.003;
85	  const cost = (tokens / 1000) * costPer1k;
86	  if (cost < 0.01) return "<$0.01";
87	  return `$${cost.toFixed(2)}`;
88	}
89	
90	export function shortProjectName(projectDir: string): string {
91	  const parts = projectDir.split("/").filter(Boolean);
92	  return parts.length > 0 ? parts[parts.length - 1] : projectDir;
93	}
