83	
84	      <Card>
85	        <CardHeader>
86	          <CardTitle>All Projects</CardTitle>
87	          <CardDescription>
88	            {projects.length} project{projects.length !== 1 ? "s" : ""} tracked
89	          </CardDescription>
90	        </CardHeader>
91	        <CardContent>
92	          <Table>
93	            <TableHeader>
94	              <TableRow>
95	                <TableHead>Project</TableHead>
96	                <TableHead className="text-right">Tokens Saved</TableHead>
97	                <TableHead className="text-right">Savings</TableHead>
98	                <TableHead className="text-right">Events</TableHead>
99	                <TableHead className="text-right">Est. Cost Saved</TableHead>
100	                <TableHead className="text-right">Last Active</TableHead>
101	              </TableRow>
