133	                      {estimateCost(p.total_saved)}
134	                    </TableCell>
135	                    <TableCell className="text-right text-sm text-muted-foreground">
136	                      {formatRelativeTime(p.last_event_at)}
137	                    </TableCell>
138	                  </TableRow>
139	                );
140	              })}
141	            </TableBody>
142	          </Table>
143	        </CardContent>
144	      </Card>
145	    </div>
146	  );
147	}
148	
149	function formatRelativeTime(iso: string): string {
150	  const date = new Date(iso);
151	  const now = new Date();
152	  const diffMs = now.getTime() - date.getTime();
153	  const diffH = Math.floor(diffMs / (1000 * 60 * 60));
154	
155	  if (diffH < 1) return "just now";
156	  if (diffH < 24) return `${diffH}h ago`;
157	  const diffD = Math.floor(diffH / 24);
158	  if (diffD < 30) return `${diffD}d ago`;
159	  return date.toLocaleDateString();
160	}
